j = {x['name']: x for x in ${j2}['joints']}
assert abs(j['elbow']['q'] + 1.0) < 0.05 and abs(j['shoulder_pitch']['q'] - 0.3) < 0.05, j
assert abs(j['elbow']['target'] + 1.0) < 1e-6, j['elbow']

from nuka.editor.app import ActionError
try:
    app.actions.run('edit.apply', ops=[{'target': ${g0}['joints'][0]['path'], 'field': 'static', 'after': True}])
except ActionError as e:
    assert 'root link can be static' in str(e), e
else:
